import app from 'flarum/forum/app';
import { t } from '../../common/api';
export function formatDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleString(app.translator.getLocale() || undefined, {
    dateStyle: 'medium',
    timeStyle: 'short'
  });
}
export function pill(status) {
  return m("span", {
    className: 'Gauntlet-pill is-' + status
  }, t('status.' + status));
}

/** An avatar from a plain person record (not a store model), or their initial. */
export function personAvatar(person) {
  if (person.avatarUrl) return m("img", {
    className: "Avatar",
    src: person.avatarUrl,
    alt: "",
    loading: "lazy",
    decoding: "async"
  });
  const name = person.displayName || '?';
  return m("span", {
    className: "Avatar",
    style: {
      '--avatar-bg': hue(name),
      color: '#fff'
    }
  }, name.charAt(0).toUpperCase());
}

/** A stable colour per name, for marks with no picture. */
export function hue(name) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) % 360;
  return `hsl(${h} 45% 45%)`;
}
flarum.reg.add('ernestdefoe-gauntlet', 'forum/components/bits', { formatDate: formatDate,pill: pill,personAvatar: personAvatar,hue: hue, });